// 1. Open the explicitly attached JSON model; the caller owns the input file.
input, err := os.Open("model.json")
if err != nil { panic(err) }
model, err := tabular.Load(input)
closeErr := input.Close()
if err != nil { panic(err) }
defer model.Close()
if closeErr != nil { panic(closeErr) }

// 2. Supply new predictor values in the same units as the training column.
newHours := []float64{7, 8, 9}
predicted, err := model.Predict(newHours)
if err != nil { panic(err) }
for i, x := range newHours { fmt.Printf("hours=%.2f predicted score=%.6f\n", x, predicted[i]) }
fmt.Println("Predictions only: no observed responses were supplied for evaluation.")

// 3. Close invalidates the model; reopening requires another explicit Load.
if err = model.Close(); err != nil { panic(err) }
if _, err = model.Predict(newHours); err == nil { panic("closed model unexpectedly predicts") }
fmt.Println("Model closed.")
